// Sprawdza, czy węzeł Code w Twoim n8n ma wszystko, czego potrzebuje bot „Dom”.
// Uruchamiany co 10 s: licznik "count" musi rosnąć 1, 2, 3… (stan przetrwał między uruchomieniami).
const out = { count: 0, http: false, fullResponse: false, env: false, staticData: false, timer: false, binary: false, urlSearchParams: false, base64: false, runners: null, errors: {} };

try {
  const state = $getWorkflowStaticData('global');
  state.count = (state.count || 0) + 1;
  out.count = state.count;
  out.staticData = true;
} catch (e) { out.errors.staticData = String(e.message || e); }

try {
  await this.helpers.httpRequest({ method: 'GET', url: 'https://api.telegram.org' });
  out.http = true;
} catch (e) { out.errors.http = String(e.message || e); }

try {
  const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.telegram.org/bot0/getMe', json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
  out.fullResponse = typeof res.statusCode === 'number' && res.statusCode >= 400;
} catch (e) { out.errors.fullResponse = String(e.message || e); }

try {
  out.env = typeof $env.GENERIC_TIMEZONE === 'string' && $env.GENERIC_TIMEZONE.length > 0;
  out.runners = $env.N8N_RUNNERS_ENABLED ?? null;
} catch (e) { out.errors.env = String(e.message || e); }

try {
  const t0 = Date.now();
  await new Promise((resolve) => setTimeout(resolve, 200));
  out.timer = Date.now() - t0 >= 150;
} catch (e) { out.errors.timer = String(e.message || e); }

try {
  const buf = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.google.com/favicon.ico', encoding: 'arraybuffer' });
  out.binary = (buf?.byteLength ?? buf?.length ?? 0) > 0;
} catch (e) { out.errors.binary = String(e.message || e); }

try {
  out.urlSearchParams = new URLSearchParams({ a: '1' }).toString() === 'a=1';
} catch (e) { out.errors.urlSearchParams = String(e.message || e); }

try {
  out.base64 = typeof Buffer !== 'undefined' || typeof btoa === 'function';
} catch (e) { out.errors.base64 = String(e.message || e); }

return [{ json: out }];
